    public record RetirementView(LocalDate from, LocalDate to) {
    }

    /** One of a person's grades, from its from-date (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
    }

    /**
     * A person as shown, with their grade and their own terms in force on the sheet's today (and their terms from the beginning of time) and every grade with its from-date, with how many statements they have had and the due-total and date of the last one. */
    public record PersonView(Long id, String name, String grade, Integer terms, Integer undatedTerms, String contact, String tags, long version, int statementCount,
            String statedTotal, LocalDate statementDate, boolean retired, LocalDate retiredFrom, boolean held,
            List<Long> patronIds, List<String> patronShares, List<GradeView> grades, List<HoldView> holds, boolean watched,
            List<String> aliases, boolean clashing, String origin, List<RetirementView> retirements,
            List<String> snapshotLines, List<String> statementLines, String flag) {

        static PersonView of(Person person, LocalDate today, StatementSummary statements, List<Long> patronIds,
                boolean watched, List<String> aliases, Set<String> keysInTree, List<String> snapshotLines) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today), person.termsOn(today),
                    person.getTerms(),
